--- a/src/factura.mjs
+++ b/src/factura.mjs
@@ -8,15 +8,19 @@ export function validarNit(nit) {
 }

 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
-export function calcularFactura(items) {
+// RF-006: descuento global entero (0 a 100) sobre el total de líneas; IVA y neto se calculan sobre el total descontado.
+export function calcularFactura(items, { descuentoGlobal = 0 } = {}) {
+  if (!Number.isInteger(descuentoGlobal) || descuentoGlobal < 0 || descuentoGlobal > 100)
+    throw new RangeError("Descuento global inválido: debe ser un entero de 0 a 100");
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
-  let totalCentavos = 0;
+  let subtotalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    subtotalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  const totalCentavos = subtotalCentavos - Math.round((subtotalCentavos * descuentoGlobal) / 100);
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
   return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
 }
diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..d92ea52 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -22,6 +22,37 @@ test("ADR-001: montos en centavos enteros", () => {
   assert.throws(() => calcularFactura([]));
 });

+const LINEAS_DESC = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("RF-006: descuento global en porcentaje sobre el total, IVA y neto sobre el total descontado", () => {
+  assert.deepEqual(calcularFactura(LINEAS_DESC, { descuentoGlobal: 10 }), { totalCentavos: 9945, ivaCentavos: 1293, netoCentavos: 8652 });
+});
+
+test("RF-006: sin descuento o con 0 el resultado no cambia", () => {
+  const base = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS_DESC), base);
+  assert.deepEqual(calcularFactura(LINEAS_DESC, {}), base);
+  assert.deepEqual(calcularFactura(LINEAS_DESC, { descuentoGlobal: 0 }), base);
+});
+
+test("RF-006: 100 % deja la factura en cero", () => {
+  assert.deepEqual(calcularFactura(LINEAS_DESC, { descuentoGlobal: 100 }), { totalCentavos: 0, ivaCentavos: 0, netoCentavos: 0 });
+});
+
+test("RF-006: descuento no entero o fuera de 0-100 se rechaza", () => {
+  for (const d of [-1, 101, 10.5, NaN, "10", null])
+    assert.throws(() => calcularFactura(LINEAS_DESC, { descuentoGlobal: d }), RangeError, String(d));
+});
+
+test("RF-006 + ADR-001: el redondeo del descuento deja centavos enteros", () => {
+  const f = calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 101 }], { descuentoGlobal: 33 });
+  assert.deepEqual(f, { totalCentavos: 68, ivaCentavos: 9, netoCentavos: 59 });
+  for (const v of Object.values(f)) assert.ok(Number.isInteger(v));
+});
+
 test("RF-003: una factura emitida no se puede modificar", () => {
   const f = emitirFactura({ numero: 7, nit: "1023456", razonSocial: "Cliente SA", items: [{ cantidad: 1, precioUnitarioCentavos: 1000 }] });
   assert.equal(f.estado, "emitida");
